import React, { useCallback, useMemo, useState } from 'react';
import { format, parseISO } from 'date-fns';
import {
  Button,
  Input,
  LeaveConfirmModal,
  SearchInput,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  useDirtyTracking,
  useLeaveConfirm,
} from '@linm-soft-org/linm-web-common-components';
import { createCustomerSearchConfig } from '../../../components/search';
import type { CustomerDto } from '../../../services/master/models';
import {
  queryShippingOrderAdjustments,
  saveShippingOrderAdjustments,
  type ShippingOrderAdjustmentDetail,
  type ShippingOrderAdjustmentFilterQuery,
  type ShippingOrderAdjustmentMaster,
} from '../../../services/shippingOrderAdjustments/endpoint';
import { useShippingOrderAdjustmentPermissions } from '../../../hooks/useShippingOrderAdjustmentPermissions';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import df from '../../../styles/documentForm.module.css';

const TITLE = 'Quyết toán lệnh xuất hàng';

type DetailDraft = ShippingOrderAdjustmentDetail & { slDcText: string };

type AppliedFilter = ShippingOrderAdjustmentFilterQuery;

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function todayYmd(): string {
  return format(new Date(), 'yyyy-MM-dd');
}

function normalizeDates(ngayCt1: string, ngayCt2: string): { ngayCt1: string; ngayCt2: string } {
  const a = ngayCt1.trim();
  const b = ngayCt2.trim();
  if (!a && !b) {
    const t = todayYmd();
    return { ngayCt1: t, ngayCt2: t };
  }
  if (!a) return { ngayCt1: b, ngayCt2: b };
  if (!b) return { ngayCt1: a, ngayCt2: a };
  return { ngayCt1: a, ngayCt2: b };
}

function showDate(value: string | null | undefined): string {
  if (!value) return '';
  const parsed = parseISO(value.length === 10 ? `${value}T00:00:00` : value);
  if (Number.isNaN(parsed.getTime())) return value;
  return format(parsed, 'dd/MM/yyyy');
}

function showQty(value: number | null | undefined): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value ?? 0);
}

function round4(value: number): string {
  const factor = 10000;
  const scaled = value * factor;
  const rounded = scaled < 0 ? -Math.round(Math.abs(scaled)) : Math.round(scaled);
  return String(rounded / factor);
}

function parseQty(text: string): number {
  const n = Number(String(text).replace(',', '.').trim());
  return Number.isFinite(n) ? n : 0;
}

function toDraft(rows: ShippingOrderAdjustmentDetail[]): DetailDraft[] {
  return rows.map(r => ({ ...r, slDcText: round4(r.slDc) }));
}

const QuyetToanHdlPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canWrite } = useShippingOrderAdjustmentPermissions();
  const customerSearch = useMemo(() => createCustomerSearchConfig(), []);

  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useLeaveConfirm({
    message: 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.',
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [ngayCt1, setNgayCt1] = useState('');
  const [ngayCt2, setNgayCt2] = useState('');
  const [lenhSo, setLenhSo] = useState('');
  const [maKh, setMaKh] = useState('');
  const [maKhKey, setMaKhKey] = useState('');
  const [nhKh1, setNhKh1] = useState('');
  const [nhKh2, setNhKh2] = useState('');
  const [nhKh3, setNhKh3] = useState('');

  const [appliedFilter, setAppliedFilter] = useState<AppliedFilter | null>(null);
  const [masters, setMasters] = useState<ShippingOrderAdjustmentMaster[]>([]);
  const [allDetails, setAllDetails] = useState<ShippingOrderAdjustmentDetail[]>([]);
  const [selectedSttRec, setSelectedSttRec] = useState<string | null>(null);
  const [details, setDetails] = useState<DetailDraft[]>([]);
  const [hasViewed, setHasViewed] = useState(false);
  const [loadingView, setLoadingView] = useState(false);
  const [loadingSave, setLoadingSave] = useState(false);
  const [errorText, setErrorText] = useState<string | null>(null);
  const [detailDirty, setDetailDirty] = useState(false);

  const setDirty = useCallback(
    (dirty: boolean) => {
      setDetailDirty(dirty);
      if (dirty) markDirty();
      else markClean();
    },
    [markClean, markDirty],
  );

  const applyQueryResult = useCallback(
    (
      result: { masters: ShippingOrderAdjustmentMaster[]; details: ShippingOrderAdjustmentDetail[] },
      preferSttRec?: string | null,
    ) => {
      setMasters(result.masters);
      setAllDetails(result.details);
      setHasViewed(true);
      setDirty(false);

      if (result.masters.length === 0) {
        setSelectedSttRec(null);
        setDetails([]);
        return;
      }

      const prefer =
        preferSttRec && result.masters.some(m => m.sttRec === preferSttRec)
          ? preferSttRec
          : result.masters[0].sttRec;
      setSelectedSttRec(prefer);
      setDetails(toDraft(result.details.filter(d => d.sttRec === prefer)));
    },
    [setDirty],
  );

  const runView = useCallback(
    async (filter: AppliedFilter, preferSttRec?: string | null) => {
      setLoadingView(true);
      setErrorText(null);
      try {
        const result = await queryShippingOrderAdjustments(filter);
        setAppliedFilter(filter);
        applyQueryResult(result, preferSttRec);
      } catch (err) {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được quyết toán lệnh'),
          type: 'error',
        });
      } finally {
        setLoadingView(false);
      }
    },
    [applyQueryResult, dispatch],
  );

  const handleView = useCallback(() => {
    const company = sessionCompany();
    if (!company) {
      setErrorText('Không xác định đơn vị');
      return;
    }
    const dates = normalizeDates(ngayCt1, ngayCt2);
    setNgayCt1(dates.ngayCt1);
    setNgayCt2(dates.ngayCt2);
    if (!dates.ngayCt1 || !dates.ngayCt2) {
      setErrorText('Chọn khoảng ngày');
      return;
    }

    const filter: AppliedFilter = {
      ngayCt1: dates.ngayCt1,
      ngayCt2: dates.ngayCt2,
      lenhSo: lenhSo.trim() || undefined,
      maKh: maKh.trim() || undefined,
      nhKh1: nhKh1.trim() || undefined,
      nhKh2: nhKh2.trim() || undefined,
      nhKh3: nhKh3.trim() || undefined,
    };
    void runView(filter);
  }, [lenhSo, maKh, ngayCt1, ngayCt2, nhKh1, nhKh2, nhKh3, runView]);

  const selectMaster = useCallback(
    (sttRec: string) => {
      if (sttRec === selectedSttRec) return;
      const doSelect = () => {
        setSelectedSttRec(sttRec);
        setDetails(toDraft(allDetails.filter(d => d.sttRec === sttRec)));
        setDirty(false);
        setErrorText(null);
      };
      if (detailDirty) {
        guardedNavigate(() => doSelect());
        return;
      }
      doSelect();
    },
    [allDetails, detailDirty, guardedNavigate, selectedSttRec, setDirty],
  );

  const onSlDcChange = useCallback(
    (sttRec0: string, text: string) => {
      if (!canWrite) return;
      setDetails(prev =>
        prev.map(row => (row.sttRec0 === sttRec0 ? { ...row, slDcText: text } : row)),
      );
      setDirty(true);
      setErrorText(null);
    },
    [canWrite, setDirty],
  );

  const onSlDcBlur = useCallback(
    (sttRec0: string) => {
      setDetails(prev =>
        prev.map(row => {
          if (row.sttRec0 !== sttRec0) return row;
          const n = parseQty(row.slDcText);
          return { ...row, slDcText: round4(n), slDc: n };
        }),
      );
    },
    [],
  );

  const handleSave = useCallback(async () => {
    const company = sessionCompany();
    if (!company) {
      setErrorText('Không xác định đơn vị');
      return;
    }
    if (!selectedSttRec) {
      setErrorText('Chọn một lệnh');
      return;
    }
    if (!detailDirty || !canWrite) return;

    const master = masters.find(m => m.sttRec === selectedSttRec);
    if (!master) {
      setErrorText('Chọn một lệnh');
      return;
    }

    setLoadingSave(true);
    setErrorText(null);
    try {
      await saveShippingOrderAdjustments({
        sttRec: selectedSttRec,
        ngayCt: master.ngayCt,
        soSo: master.soSo,
        lines: details.map(d => ({
          sttRec0: d.sttRec0,
          maVt: d.maVt,
          slDc: parseQty(d.slDcText),
          soSo: d.soSo,
          maKhoI: d.maKhoI,
        })),
      });
      dispatchAppToast(dispatch, { message: 'Đã lưu điều chỉnh', type: 'success' });
      setDirty(false);
      if (appliedFilter) {
        await runView(appliedFilter, selectedSttRec);
      }
    } catch (err) {
      const msg = getApiErrorMessage(err, 'Lưu điều chỉnh thất bại');
      setErrorText(msg);
      dispatchAppToast(dispatch, { message: msg, type: 'error' });
    } finally {
      setLoadingSave(false);
    }
  }, [
    appliedFilter,
    canWrite,
    detailDirty,
    details,
    dispatch,
    masters,
    runView,
    selectedSttRec,
    setDirty,
  ]);

  const onFilterKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const saveDisabled =
    !hasViewed || !selectedSttRec || !detailDirty || loadingView || loadingSave || !canWrite;

  return (
    <div className={df.page} data-testid="ct-quyet-toan-hdl-page">
      <h1 data-testid="ct-quyet-toan-hdl-title">{TITLE}</h1>

      <div>
        <Button
          variant="primary"
          data-testid="ct-quyet-toan-hdl-view-btn"
          disabled={loadingView || loadingSave}
          onClick={handleView}
        >
          Xem
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-quyet-toan-hdl-save-btn"
          disabled={saveDisabled}
          onClick={() => void handleSave()}
        >
          Lưu
        </Button>
      </div>

      {errorText ? (
        <div className={df.errorBanner} data-testid="ct-quyet-toan-hdl-error">
          {errorText}
        </div>
      ) : null}

      <section className={df.section} data-testid="ct-quyet-toan-hdl-filters">
        <h2 className={df.sectionTitle}>Điều kiện lọc</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label htmlFor="ct-quyet-toan-hdl-field-ngayCt1">Từ ngày</label>
            <Input
              id="ct-quyet-toan-hdl-field-ngayCt1"
              type="date"
              data-testid="ct-quyet-toan-hdl-field-ngayCt1"
              value={ngayCt1}
              onChange={e => setNgayCt1(e.target.value)}
              onKeyDown={onFilterKeyDown}
            />
          </div>
          <div className={df.field}>
            <label htmlFor="ct-quyet-toan-hdl-field-ngayCt2">Đến ngày</label>
            <Input
              id="ct-quyet-toan-hdl-field-ngayCt2"
              type="date"
              data-testid="ct-quyet-toan-hdl-field-ngayCt2"
              value={ngayCt2}
              onChange={e => setNgayCt2(e.target.value)}
              onKeyDown={onFilterKeyDown}
            />
          </div>
          <div className={df.field}>
            <label htmlFor="ct-quyet-toan-hdl-field-lenhSo">Số lệnh</label>
            <Input
              id="ct-quyet-toan-hdl-field-lenhSo"
              data-testid="ct-quyet-toan-hdl-field-lenhSo"
              value={lenhSo}
              onChange={e => setLenhSo(e.target.value)}
              onKeyDown={onFilterKeyDown}
            />
          </div>
          <div className={df.field}>
            <label>Mã khách</label>
            <SearchInput
              config={customerSearch}
              value={maKhKey}
              primaryDisplay={maKh}
              data-testid="ct-quyet-toan-hdl-field-maKh"
              onChange={(item: CustomerDto) => {
                setMaKh(item?.code ?? '');
                setMaKhKey(item?.customerId ?? '');
              }}
              onClear={() => {
                setMaKh('');
                setMaKhKey('');
              }}
            />
          </div>
          <div className={df.field}>
            <label htmlFor="ct-quyet-toan-hdl-field-nhKh1">Nhóm khách 1</label>
            <Input
              id="ct-quyet-toan-hdl-field-nhKh1"
              data-testid="ct-quyet-toan-hdl-field-nhKh1"
              value={nhKh1}
              onChange={e => setNhKh1(e.target.value)}
              onKeyDown={onFilterKeyDown}
            />
          </div>
          <div className={df.field}>
            <label htmlFor="ct-quyet-toan-hdl-field-nhKh2">Nhóm khách 2</label>
            <Input
              id="ct-quyet-toan-hdl-field-nhKh2"
              data-testid="ct-quyet-toan-hdl-field-nhKh2"
              value={nhKh2}
              onChange={e => setNhKh2(e.target.value)}
              onKeyDown={onFilterKeyDown}
            />
          </div>
          <div className={df.field}>
            <label htmlFor="ct-quyet-toan-hdl-field-nhKh3">Nhóm khách 3</label>
            <Input
              id="ct-quyet-toan-hdl-field-nhKh3"
              data-testid="ct-quyet-toan-hdl-field-nhKh3"
              value={nhKh3}
              onChange={e => setNhKh3(e.target.value)}
              onKeyDown={onFilterKeyDown}
            />
          </div>
        </div>
      </section>

      <section className={df.section}>
        <h2 className={df.sectionTitle}>Lệnh xuất hàng</h2>
        <div className={df.tableWrapper}>
          <table className={df.linesTable} data-testid="ct-quyet-toan-hdl-master-grid">
            <thead>
              <tr>
                <th>Tag</th>
                <th>Số lệnh</th>
                <th>Ngày tháng</th>
                <th>Mã khách hàng</th>
                <th>Tên khách hàng</th>
              </tr>
            </thead>
            <tbody>
              {masters.map((row, index) => {
                const selected = selectedSttRec === row.sttRec;
                return (
                  <tr
                    key={row.sttRec}
                    data-testid={`ct-quyet-toan-hdl-master-row-${index}`}
                    aria-selected={selected}
                    onClick={() => selectMaster(row.sttRec)}
                    style={{ cursor: 'pointer', background: selected ? 'rgba(24,144,255,0.08)' : undefined }}
                  >
                    <td style={{ textAlign: 'center' }}>
                      <input type="radio" readOnly checked={selected} aria-label={`Chọn ${row.soSo}`} />
                    </td>
                    <td>{row.soSo}</td>
                    <td>{showDate(row.ngayCt)}</td>
                    <td>{row.maKh}</td>
                    <td>{row.tenKh?.trim() ? row.tenKh : '—'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {hasViewed && masters.length === 0 ? (
          <div data-testid="ct-quyet-toan-hdl-master-empty">Không có lệnh xuất hàng</div>
        ) : null}
      </section>

      <section className={df.section}>
        <h2 className={df.sectionTitle}>Chi tiết vật tư</h2>
        <div className={df.tableWrapper}>
          <table className={df.linesTable} data-testid="ct-quyet-toan-hdl-detail-grid">
            <thead>
              <tr>
                <th>Mã vật tư</th>
                <th>Tên vật tư</th>
                <th>ĐVT</th>
                <th>Mã kho</th>
                <th>Số lượng lệnh</th>
                <th>Số lượng đã xuất</th>
                <th>Số lượng điều chỉnh</th>
                <th>Số lượng còn lại</th>
                <th>Diễn giải</th>
              </tr>
            </thead>
            <tbody>
              {details.map(row => {
                const slDcNum = parseQty(row.slDcText);
                const slCl = row.slSo + slDcNum - row.slXuat;
                return (
                  <tr key={`${row.sttRec0}-${row.maVt}`}>
                    <td>{row.maVt}</td>
                    <td>{row.tenVt?.trim() ? row.tenVt : '—'}</td>
                    <td>{row.dvt?.trim() ? row.dvt : '—'}</td>
                    <td>{row.maKhoI?.trim() ? row.maKhoI : '—'}</td>
                    <td style={{ textAlign: 'right' }}>{showQty(row.slSo)}</td>
                    <td style={{ textAlign: 'right' }}>{showQty(row.slXuat)}</td>
                    <td style={{ textAlign: 'right' }}>
                      <Input
                        inputMode="decimal"
                        data-testid={`ct-quyet-toan-hdl-field-slDc-${row.sttRec0}`}
                        value={row.slDcText}
                        disabled={!canWrite || loadingSave}
                        readOnly={!canWrite}
                        onChange={e => onSlDcChange(row.sttRec0, e.target.value)}
                        onBlur={() => onSlDcBlur(row.sttRec0)}
                      />
                    </td>
                    <td style={{ textAlign: 'right' }}>{showQty(slCl)}</td>
                    <td>{row.dienGiai?.trim() ? row.dienGiai : '—'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {hasViewed && selectedSttRec && details.length === 0 ? (
          <div data-testid="ct-quyet-toan-hdl-detail-empty">Không có dòng vật tư</div>
        ) : null}
      </section>

      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default QuyetToanHdlPage;
