import { apiClient, unwrap, type BffResponse } from '../api';

export interface ShippingOrderAdjustmentMaster {
  sttRec: string;
  tag: number;
  soSo: string;
  ngayCt: string;
  maKh: string;
  tenKh: string;
}

export interface ShippingOrderAdjustmentDetail {
  sttRec: string;
  sttRec0: string;
  soSo: string;
  maVt: string;
  tenVt: string;
  dvt: string;
  maKhoI: string;
  maDbI?: string | null;
  slSo: number;
  slXuat: number;
  slDc: number;
  slCl: number;
  dienGiai: string;
}

export interface ShippingOrderAdjustmentQueryResult {
  masters: ShippingOrderAdjustmentMaster[];
  details: ShippingOrderAdjustmentDetail[];
}

export interface ShippingOrderAdjustmentFilterQuery {
  ngayCt1: string;
  ngayCt2: string;
  lenhSo?: string;
  maKh?: string;
  nhKh1?: string;
  nhKh2?: string;
  nhKh3?: string;
}

export interface ShippingOrderAdjustmentSaveLine {
  sttRec0: string;
  maVt: string;
  slDc: number;
  soSo?: string;
  maKhoI?: string;
}

export interface ShippingOrderAdjustmentSaveBody {
  sttRec: string;
  ngayCt?: string;
  soSo?: string;
  lines: ShippingOrderAdjustmentSaveLine[];
}

export interface ShippingOrderAdjustmentSaveResult {
  sttRec: string;
  lineCount: number;
}

function queryString(query: ShippingOrderAdjustmentFilterQuery): string {
  const params = new URLSearchParams();
  params.set('ngayCt1', query.ngayCt1);
  params.set('ngayCt2', query.ngayCt2);
  const optional: Array<[string, string | undefined]> = [
    ['lenhSo', query.lenhSo],
    ['maKh', query.maKh],
    ['nhKh1', query.nhKh1],
    ['nhKh2', query.nhKh2],
    ['nhKh3', query.nhKh3],
  ];
  for (const [key, value] of optional) {
    const trimmed = (value ?? '').trim();
    if (trimmed) params.set(key, trimmed);
  }
  const qs = params.toString();
  return qs ? `?${qs}` : '';
}

export async function queryShippingOrderAdjustments(
  query: ShippingOrderAdjustmentFilterQuery,
): Promise<ShippingOrderAdjustmentQueryResult> {
  const res = await apiClient.get<BffResponse<ShippingOrderAdjustmentQueryResult>>(
    `/sales/shipping-order-adjustments${queryString(query)}`,
  );
  return unwrap(res);
}

export async function saveShippingOrderAdjustments(
  body: ShippingOrderAdjustmentSaveBody,
): Promise<ShippingOrderAdjustmentSaveResult> {
  const res = await apiClient.put<BffResponse<ShippingOrderAdjustmentSaveResult>>(
    '/sales/shipping-order-adjustments',
    body,
  );
  return unwrap(res);
}
